  }, [sceneEditorProps]);

  const syncProgramStateAndStagedScene = useCallback(
    (nextProgramState: ProgramState | null) => {
      setProgramState(nextProgramState);
      setSelectedScene(() => {
        if (!nextProgramState) {
          return null;
        }

        const nextStagedSceneId =
          typeof nextProgramState.stagedSceneId === "number" &&
