  realtimeConnected: boolean;
  fadeToBlack: boolean;
  workspace: ConsoleWorkspace;
  onWorkspaceChange: (workspace: ConsoleWorkspace) => void;
  onTransitionChange: (transitionId: string) => void;
  onStageScene: (
    sceneId: number | null,
  ) => Promise<void | boolean> | void | boolean;
  onTake: () => Promise<void> | void;
  onCut: () => Promise<void> | void;
  takeBusy?: boolean;
  takeError?: string | null;
  onFadeToBlack: () => void;
}

export function BroadcastSwitcherDeck(props: Props) {
  const preferences = useConsolePreferences();
  const latestPropsRef = useRef(props);
  latestPropsRef.current = props;
  const { touchMode, shortcutsEnabled } = preferences.profile;
  const dockWidth = preferences.profile.dockWidth ?? 300;
  const pendingStageRef = useRef<Promise<void>>(Promise.resolve());
  const [ftbArmed, setFtbArmed] = useState(false);
  const [sourceSearch, setSourceSearch] = useState("");
  const stageFailedRef = useRef(false);
  const [stageError, setStageError] = useState<string | null>(null);
  const ftbArmTimerRef = useRef<number | null>(null);
  useEffect(() => {
    stageFailedRef.current = false;
    setStageError(null);
  }, [props.programId]);

  useEffect(() => {
    return () => {
      if (ftbArmTimerRef.current !== null) {
        window.clearTimeout(ftbArmTimerRef.current);
      }
    };
  }, []);

  const stageScene = (sceneId: number | null) => {
    stageFailedRef.current = false;
    setStageError(null);
    const pending = Promise.resolve()
      .then(() => props.onStageScene(sceneId))
      .then((result) => {
        if (result === false)
          throw new Error(
            "Could not prepare Preview. Program has not changed.",
          );
      })
      .catch((error: unknown) => {
        stageFailedRef.current = true;
        setStageError(
          error instanceof Error ? error.message : "Could not prepare Preview.",
        );
      });
    pendingStageRef.current = pending;
    return pending;
  };
  const takeStagedScene = async () => {
    await pendingStageRef.current;
    await new Promise<void>((resolve) =>
      window.requestAnimationFrame(() => resolve()),
    );
    if (!stageFailedRef.current && !latestPropsRef.current.takeBusy)
      await latestPropsRef.current.onTake();
  };
  const cutStagedScene = async () => {
    await pendingStageRef.current;
    await new Promise<void>((resolve) =>
      window.requestAnimationFrame(() => resolve()),
    );
    if (!stageFailedRef.current && !latestPropsRef.current.takeBusy)
      await latestPropsRef.current.onCut();
  };
  const requestFadeToBlack = () => {
    if (props.fadeToBlack || ftbArmed) {
      if (ftbArmTimerRef.current !== null) {
        window.clearTimeout(ftbArmTimerRef.current);
        ftbArmTimerRef.current = null;
      }
      setFtbArmed(false);
      latestPropsRef.current.onFadeToBlack();
      return;
    }

    setFtbArmed(true);
    ftbArmTimerRef.current = window.setTimeout(() => {
      setFtbArmed(false);
      ftbArmTimerRef.current = null;
    }, 3_000);
  };

  useEffect(() => {
    if (!shortcutsEnabled) return;
    const handleShortcut = (event: KeyboardEvent) => {
      if (blocksBroadcastShortcut(event.target)) return;
      if (event.altKey && event.key.toLowerCase() === "b") {
        event.preventDefault();
        requestFadeToBlack();
      } else if (
        !event.altKey &&
        !event.ctrlKey &&
        !event.metaKey &&
        !event.shiftKey &&
        event.code === "Space"
      ) {
        event.preventDefault();
        void takeStagedScene();
      } else if (
        !event.altKey &&
        !event.ctrlKey &&
        !event.metaKey &&
        !event.shiftKey &&
        event.key.toLowerCase() === "c"
      ) {
        event.preventDefault();
        void cutStagedScene();
      } else if (event.key === "Escape") {
        event.preventDefault();
        void stageScene(null);
      }
    };
    window.addEventListener("keydown", handleShortcut);
    return () => window.removeEventListener("keydown", handleShortcut);
  }, [
    props.onCut,
    props.onFadeToBlack,
    props.onStageScene,
    props.onTake,
    ftbArmed,
    props.fadeToBlack,
    shortcutsEnabled,
  ]);

  const selectWorkspace = (workspace: ConsoleWorkspace) => {
    preferences.updateProfile({ workspace });
    props.onWorkspaceChange(workspace);
  };
  const toggleTouch = () => {
    const next = !touchMode;
    preferences.updateProfile({ touchMode: next });
  };
  const toggleShortcuts = () => {
    const next = !shortcutsEnabled;
    preferences.updateProfile({ shortcutsEnabled: next });
  };

  const workspace =
    props.workspace === "graphics" ? "director" : props.workspace;

  const filteredScenes = props.scenes.filter((scene) =>
    scene.name.toLocaleLowerCase().includes(sourceSearch.toLocaleLowerCase()),
  );
  const sourceBank = (
    <aside
      className="switcher-source-bank order-3 col-span-2 flex min-h-0 flex-col rounded-[var(--radius-ui)] border border-sand/30 bg-dark-sand p-3 md:order-1 md:col-span-1 md:row-span-2"
      aria-label="Assigned scenes"
    >
      <div className="console-panel-heading mb-2 flex items-center justify-between gap-2">
        <h2 className="text-xs font-bold uppercase tracking-wider text-text-secondary">
          Sources
        </h2>
        <span className="text-xs text-text-secondary">
          {props.scenes.length}
        </span>
      </div>
      <div className="switcher-source-search">
        <Input
          aria-label="Search scenes"
          placeholder="Find a scene…"
          value={sourceSearch}
          onChange={(event) => setSourceSearch(event.target.value)}
        />
      </div>
      <div className="switcher-source-list mt-2 grid max-h-24 gap-1.5 overflow-y-auto sm:grid-cols-2 md:max-h-[23rem] md:grid-cols-1">
        {filteredScenes.map((scene) => {
          const isPreview = scene.id === props.stagedScene?.id;
          const isProgram = scene.id === props.activeScene?.id;
          return (
            <TooltipButton
              key={scene.id}
              type="button"
              onClick={() => void stageScene(scene.id)}
              aria-pressed={isPreview}
              className={`switcher-source flex min-h-12 items-center justify-between gap-2 rounded-[var(--radius-button)] border px-3 py-2 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-blue ${isPreview ? "border-accent-yellow bg-accent-yellow/10" : isProgram ? "border-terracotta/50 bg-terracotta/10" : "border-sand/30 bg-dark-sand hover:bg-sand/10"}`}
            >
              <span className="switcher-source-index">
                {String(props.scenes.indexOf(scene) + 1).padStart(2, "0")}
              </span>
              <span className="min-w-0 flex-1 truncate text-sm font-semibold">
                {scene.name}
              </span>
              <span
                className={`shrink-0 text-[10px] font-bold uppercase ${isPreview ? "text-accent-yellow" : isProgram ? "text-terracotta" : "text-text-secondary"}`}
              >
                {isPreview && isProgram
                  ? "Preview · Program"
                  : isPreview
                    ? "Preview"
                    : isProgram
                      ? "Program"
                      : "Stage"}
              </span>
            </TooltipButton>
          );
        })}
        {!filteredScenes.length && (
          <p className="col-span-full px-2 py-3 text-xs text-text-secondary">
            {props.scenes.length
              ? "No scenes match your search."
              : "No scenes assigned. Add scenes from the Library."}
          </p>
        )}
      </div>
      <p className="m-3 text-[10px] text-text-secondary">
        Select a source to prepare it in Preview.
      </p>
    </aside>
  );

  return (
    <section
      className={`broadcast-console switcher-console shrink-0 border-b border-sand/30 bg-dark-sand text-text-primary ${touchMode ? "text-base" : "text-sm"}`}
      data-console-workspace={workspace}
      data-touch-mode={touchMode}
    >
      <div className="console-toolbar">
        <div
          className="mr-2 flex items-center gap-2 font-semibold"
          title={
            props.realtimeConnected
              ? "Live updates connected"
              : "Live updates disconnected"
          }
        >
          {props.realtimeConnected ? (
            <Wifi size={16} className="text-sea" />
          ) : (
            <WifiOff size={16} className="text-accent-yellow" />
          )}
          <span>
            <span className="console-eyebrow">Studio / {props.programId}</span>
            Live control
          </span>
        </div>
        {WORKSPACES.map((option) => (
          <Button
            key={option.id}
            type="button"
            size="sm"
            variant={option.id === workspace ? "primary" : "ghost"}
            onClick={() => selectWorkspace(option.id)}
            aria-pressed={workspace === option.id}
          >
            {option.label}
          </Button>
        ))}
        <ConsoleClock />
        <details className="relative ml-auto">
          <summary className="flex cursor-pointer list-none items-center gap-1.5 rounded-[var(--radius-button)] px-2 py-1 text-xs text-text-secondary">
            <Settings2 size={15} />
            Workspace options
          </summary>
          <div className="absolute right-0 top-full z-40 mt-2 w-72 rounded-[var(--radius-ui)] border border-sand/30 bg-dark-sand p-3 shadow-xl">
            <div className="flex flex-wrap gap-2">
              <ConsolePreferenceControls programId={props.programId} />
              <IconButton
                type="button"
                size="sm"
                variant={shortcutsEnabled ? "subtle" : "ghost"}
                aria-label="Toggle keyboard shortcuts"
                aria-pressed={shortcutsEnabled}
                onClick={toggleShortcuts}
                title="Space: TAKE · C: CUT · Escape: clear Preview"
              >
                <Keyboard size={17} />
              </IconButton>
              <IconButton
                type="button"
                size="sm"
                variant={touchMode ? "subtle" : "ghost"}
                aria-label="Toggle touch mode"
                aria-pressed={touchMode}
                onClick={toggleTouch}
              >
                <Smartphone size={17} />
              </IconButton>
              <IconButton
                type="button"
                size="sm"
                variant="ghost"
                aria-label="Enter fullscreen"
                onClick={() =>
                  void document.documentElement.requestFullscreen?.()
                }
              >
                <Expand size={17} />
              </IconButton>
            </div>
            <label className="mt-3 block text-xs text-text-secondary">
              Source panel width
              <input
                type="range"
                min={260}
                max={520}
                value={dockWidth}
                onChange={(event) =>
                  preferences.updateProfile({
                    dockWidth: Number(event.target.value),
                  })
                }
                className="mt-1 w-full"
              />
            </label>
          </div>
        </details>
      </div>
      {workspace !== "audio" && (
        <div
          className="switcher-body grid grid-cols-2 gap-3 p-3 md:grid-cols-[var(--source-width)_minmax(0,1fr)_minmax(0,1fr)]"
          style={
            { "--source-width": `min(${dockWidth}px, 30vw)` } as CSSProperties
          }
        >
          {sourceBank}
          <ConfidenceMonitor
            label="PREVIEW"
            tone="preview"
            scene={props.stagedScene}
            src={`/program/${encodeURIComponent(props.programId)}?confidence=preview`}
          />
          <ConfidenceMonitor
            label="PROGRAM"
            tone="program"
            scene={props.activeScene}
            src={`/program/${encodeURIComponent(props.programId)}?confidence=program`}
          />
          <div className="switcher-transports order-4 col-span-2 rounded-[var(--radius-ui)] border border-sand/30 bg-dark-sand p-3 md:order-4">
            <div className="flex flex-wrap items-end gap-3">
              <label className="w-full min-w-0 text-xs text-text-secondary sm:w-auto sm:flex-1">
                Transition
                <select
                  value={props.transitionId}
                  onChange={(event) =>
                    props.onTransitionChange(event.target.value)
                  }
                  className="mt-1 w-full rounded-[var(--radius-button)] border border-sand/30 bg-dark-sand px-2 py-2 text-text-primary"
                >
                  {SCENE_TRANSITIONS.map((transition) => (
                    <option key={transition.id} value={transition.id}>
                      {transition.name}
                    </option>
                  ))}
                </select>
              </label>
              <BroadcastAction
                kind="cut"
                className="switcher-cut flex-1 sm:flex-none"
                disabled={!props.stagedScene || props.takeBusy}
                onClick={() => void cutStagedScene()}
              >
                CUT
              </BroadcastAction>
              <BroadcastAction
                kind="take"
                className="switcher-take flex-1 sm:flex-none"
                disabled={!props.stagedScene || props.takeBusy}
                onClick={() => void takeStagedScene()}
              >
                {props.takeBusy ? "TAKING…" : "TAKE TO PROGRAM"}
              </BroadcastAction>
            </div>
            <div className="mt-2 flex flex-wrap items-center justify-between gap-2">
              <p role="status" className="text-xs text-text-secondary">
                {props.takeBusy
                  ? "Saving Preview and taking it to Program…"
                  : props.stagedScene
                    ? `Ready: ${props.stagedScene.name}`
                    : "Choose a source to prepare the next scene."}
              </p>
              <TooltipButton
                type="button"
                onClick={requestFadeToBlack}
                aria-pressed={props.fadeToBlack}
                className={`rounded-[var(--radius-button)] border px-3 py-2 text-xs font-semibold ${props.fadeToBlack || ftbArmed ? "border-terracotta text-terracotta" : "border-sand/30 text-text-secondary hover:text-text-primary"}`}
              >
                {props.fadeToBlack
                  ? "RESTORE PROGRAM"
                  : ftbArmed
                    ? "CONFIRM FADE TO BLACK"
                    : "ARM FADE TO BLACK"}
              </TooltipButton>
            </div>
            {(props.takeError || stageError) && (
              <p
                role="alert"
                className="mt-2 rounded-[var(--radius-button)] border border-terracotta/40 bg-terracotta/10 px-3 py-2 text-sm text-terracotta"
              >
                {props.takeError || stageError}
              </p>
            )}
          </div>
        </div>
      )}
    </section>
  );
}

export { InstantsPanel } from './InstantsPanel';
export { PlaylistPanel } from './PlaylistPanel';
export { PlaylistSheetPanel } from './PlaylistSheetPanel';
export { SceneAttributesPanel } from './SceneAttributesPanel';

import { Button, Card, Field, Select, Tabs } from "@gaulatti/bleecker";
import { useEffect, useId, useMemo, useState } from "react";
import type {
  BackgroundAudioAsset,
  MediaGroup,
  MediaLabel,
  Scene,
  SceneInstantPlaybackState,
  SongCatalogItem,
} from "../../models/broadcast";
import { ComponentPropsFields, ZIndexField } from "../editors";

interface SceneAttributesPanelProps {
  selectedScene: number | null;
  scenes: Scene[];
  stagedIsOnAir: boolean;
  isSavingSceneAttributes: boolean;
  sceneAttributeSaveError: string | null;
  editableSceneComponentEntries: [string, any][];
  componentTypes: { type: string; name: string; description: string }[];
  sceneEditorProps: Record<string, any>;
  selectedSceneInstantId: number | null;
  selectedBackgroundAudioAssetId: string | null;
  selectedBackgroundAudioAsset: BackgroundAudioAsset | null;
  sceneInstantPlayback: SceneInstantPlaybackState;
  activeProgramId: string;
  backgroundAudioAssets: BackgroundAudioAsset[];
  isLoadingBackgroundAudio: boolean;
  songCatalog: SongCatalogItem[];
  mediaGroups: MediaGroup[];
  isLoadingMediaGroups: boolean;
  mediaLabels: MediaLabel[];
  isLoadingMediaLabels: boolean;
  onBlurCapture: (event: React.FocusEvent<HTMLDivElement>) => void;
  onSave: () => void;
  onCommitComponentProps: (componentType: string, props: any) => Promise<void>;
  onUpdateProp: (componentType: string, propName: string, value: any) => void;
  onReplaceProps: (componentType: string, newProps: any) => void;
  onSyncComponentProps: (componentType: string, newProps: any) => void;
  onTakeSceneInstant: (
    sceneId: number | null,
    instantId: number | null,
    mediaAssetId: string | null,
  ) => Promise<void>;
  onStopSceneInstant: () => Promise<void>;
}

export function SceneAttributesPanel({
  selectedScene,
  scenes,
  stagedIsOnAir,
  isSavingSceneAttributes,
  sceneAttributeSaveError,
  editableSceneComponentEntries,
  componentTypes,
  sceneEditorProps,
  selectedSceneInstantId,
  selectedBackgroundAudioAssetId,
  selectedBackgroundAudioAsset,
  sceneInstantPlayback,
  activeProgramId,
  backgroundAudioAssets,
  isLoadingBackgroundAudio,
  songCatalog,
  mediaGroups,
  isLoadingMediaGroups,
  mediaLabels,
  isLoadingMediaLabels,
  onBlurCapture,
  onSave,
  onCommitComponentProps,
  onUpdateProp,
  onReplaceProps,
  onSyncComponentProps,
  onTakeSceneInstant,
  onStopSceneInstant,
}: SceneAttributesPanelProps) {
  const panelId = useId();
  const [activeAttributeTab, setActiveAttributeTab] = useState<string>("");

  const attributeTabs = useMemo(
    () => [
      ...editableSceneComponentEntries.map(([componentType]) => {
        const compInfo = componentTypes.find((ct) => ct.type === componentType);
        return {
          id: componentType,
          label: compInfo?.name || componentType,
          panelId,
        };
      }),
      { id: "__scene", label: "Background audio", panelId },
    ],
    [componentTypes, editableSceneComponentEntries, panelId],
  );

  useEffect(() => {
    const hasActive = attributeTabs.some(
      (tab) => tab.id === activeAttributeTab,
    );
    if (!hasActive) {
      setActiveAttributeTab(attributeTabs[0]?.id ?? "");
    }
  }, [activeAttributeTab, attributeTabs]);

  const componentTabKey = editableSceneComponentEntries
    .map(([type]) => type)
    .join(",");
  useEffect(() => {
    setActiveAttributeTab(editableSceneComponentEntries[0]?.[0] ?? "__scene");
  }, [selectedScene, componentTabKey]);

  const activeComponentEntry = useMemo(() => {
    if (
      activeAttributeTab === "__scene" ||
      editableSceneComponentEntries.length === 0
    ) {
      return null;
    }

    const fallback = editableSceneComponentEntries[0];
    return (
      editableSceneComponentEntries.find(
        ([componentType]) => componentType === activeAttributeTab,
      ) ?? fallback
    );
  }, [activeAttributeTab, editableSceneComponentEntries]);

  if (!selectedScene) {
    return (
      <Card className="scene-preparation-empty">
        <h2 className="text-base font-semibold">Prepare the next scene</h2>
        <p className="mt-2 text-sm text-text-secondary">
          Stage a scene above to edit its attributes before taking it live.
        </p>
      </Card>
    );
  }

  return (
    <Card
      padding="none"
      className="console-scene-editor"
      onBlurCapture={onBlurCapture}
    >
      <header className="scene-preparation-heading">
        <h2>
          Prepare ·{" "}
          {scenes.find((scene) => scene.id === selectedScene)?.name ??
            "Selected scene"}
        </h2>
      </header>
      {stagedIsOnAir && (
        <p className="scene-preparation-notice rounded-[var(--radius-button)] border border-accent-yellow/40 bg-accent-yellow/10 px-3 py-2 text-xs text-accent-yellow">
          This scene is on Program. Saved changes appear live.
        </p>
      )}
      {editableSceneComponentEntries
        .filter(
          ([type, props]) =>
            type === activeComponentEntry?.[0] && props.show === false,
        )
        .map(([componentType]) => (
          <div
            key={componentType}
            role="status"
            className="scene-preparation-notice flex flex-wrap items-center justify-between gap-2 rounded-[var(--radius-button)] border border-accent-yellow/40 bg-accent-yellow/10 px-3 py-2 text-sm"
          >
            <span>
              {componentTypes.find(
                (component) => component.type === componentType,
              )?.name ?? componentType}{" "}
              is hidden.
            </span>
            <Button
              type="button"
              size="sm"
              variant="secondary"
              onClick={() => onUpdateProp(componentType, "show", true)}
            >
              Show component
            </Button>
          </div>
        ))}
      <div className="scene-preparation-tabs">
        <Tabs
          aria-label="Scene components"
          tabs={attributeTabs}
          size="sm"
          variant="enclosed"
          activeTab={activeAttributeTab}
          onChange={(id) => setActiveAttributeTab(id)}
          className="overflow-x-auto"
        />
      </div>

      <div
        className="scene-preparation-scroll"
        role="tabpanel"
        id={panelId}
        aria-label={
          attributeTabs.find((tab) => tab.id === activeAttributeTab)?.label
        }
      >
        <div className="console-props-body">
          {activeProgramId === "fifthbell" && (
            <p className="text-xs text-text-secondary dark:text-text-secondary">
              FifthBell runtime settings are stored per component metadata
              (`fifthbell-content`, `fifthbell-marquee`, `fifthbell-clock` /
              `toni-clock`).
            </p>
          )}

          {activeAttributeTab === "__scene" ? (
            <div className="space-y-3">
              <div className="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between">
                <div className="flex-1">
                  <Field label="Audio clip">
                    <Select
                      value={selectedBackgroundAudioAssetId ?? ""}
                      onChange={(value) => {
                        const nextAssetId = value.trim() || null;
                        const currentSceneInstantProps =
                          sceneEditorProps?.sceneInstant &&
                          typeof sceneEditorProps.sceneInstant === "object"
                            ? sceneEditorProps.sceneInstant
                            : {};
                        void onCommitComponentProps("sceneInstant", {
                          ...currentSceneInstantProps,
                          assetId: nextAssetId,
                          instantId: null,
                        });
                      }}
                      options={[
                        { value: "", label: "No background audio" },
                        ...backgroundAudioAssets
                          .filter((asset) => asset.enabled)
                          .map((asset) => ({
                            value: asset.id,
                            label: asset.name,
                          })),
                      ]}
                    />
                  </Field>
                  {isLoadingBackgroundAudio ? (
                    <p className="mt-1 text-xs text-text-secondary">
                      Loading background audio…
                    </p>
                  ) : null}
                </div>
                <div className="flex flex-wrap gap-2">
                  <Button
                    size="sm"
                    onClick={() =>
                      onTakeSceneInstant(
                        selectedScene,
                        selectedSceneInstantId,
                        selectedBackgroundAudioAssetId,
                      )
                    }
                    disabled={!selectedScene || !selectedBackgroundAudioAsset}
                  >
                    TAKE BG
                  </Button>
                  <Button
                    size="sm"
                    variant="secondary"
                    onClick={() => onStopSceneInstant()}
                    disabled={!sceneInstantPlayback.isPlaying}
                  >
                    STOP BG
                  </Button>
                </div>
              </div>
              <p className="text-xs text-text-secondary dark:text-text-secondary">
                {sceneInstantPlayback.isPlaying
                  ? `Playing: ${sceneInstantPlayback.instantName || "Scene instant"}`
                  : selectedBackgroundAudioAsset
                    ? `Ready: ${selectedBackgroundAudioAsset.name}`
                    : "Select background audio, then press SAVE (or TAKE BG)."}
              </p>
            </div>
          ) : activeComponentEntry ? (
            <div>
              <ComponentPropsFields
                componentType={activeComponentEntry[0]}
                props={activeComponentEntry[1]}
                updateProp={onUpdateProp}
                replaceProps={onReplaceProps}
                commitProps={onCommitComponentProps}
                syncProps={onSyncComponentProps}
                songCatalog={songCatalog}
                mediaGroups={mediaGroups}
                isLoadingMediaGroups={isLoadingMediaGroups}
                mediaLabels={mediaLabels}
                isLoadingMediaLabels={isLoadingMediaLabels}
                scenes={scenes}
                programId={activeProgramId}
                sceneId={selectedScene}
              />
              <ZIndexField
                componentType={activeComponentEntry[0]}
                props={activeComponentEntry[1]}
                updateProp={onUpdateProp}
              />
            </div>
          ) : (
            <p className="text-sm text-text-secondary dark:text-text-secondary">
              No configurable component attributes for this scene.
            </p>
          )}
        </div>
      </div>

      <div className="scene-preparation-footer">
        <div className="flex flex-wrap items-center justify-between gap-2">
          {isSavingSceneAttributes ? (
            <p className="text-xs text-text-secondary dark:text-text-secondary">
              Autosaving scene attributes…
            </p>
          ) : sceneAttributeSaveError ? (
            <p role="alert" className="text-xs text-terracotta">
              {sceneAttributeSaveError}
            </p>
          ) : (
            <span />
          )}
          <Button
            size="sm"
            variant="primary"
            onClick={() => onSave()}
            disabled={!selectedScene || isSavingSceneAttributes}
          >
            {isSavingSceneAttributes ? "Saving…" : "Save changes"}
          </Button>
        </div>
      </div>
    </Card>
  );
}

